mapper.sql:
FROM audit_log a LEFT JOIN sys_user u ON u.id = a.actor_user_id



            a.action IN ('LOGIN_SUCCEEDED', 'LOGIN_FAILED', 'LOGOUT')
            a.action NOT IN ('LOGIN_SUCCEEDED', 'LOGIN_FAILED', 'LOGOUT')


    AND  LIKE CONCAT('%', #{query.escapedUsername}, '%') ESCAPE '!'
    AND a.created_at >= #{query.from}
    AND a.created_at < #{query.to}
    AND a.result = #{query.result}
    AND (a.action = #{query.action} OR (a.action = 'OPERATION_FAILED' AND JSON_UNQUOTE(JSON_EXTRACT(a.summary_json, '$.operation')) = #{query.action}))
